{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Label text.",
      "required": true
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Visually hide the label.",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Helper text displayed below the label."
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Show an \"(optional)\" indicator.",
      "default": "false"
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Mark the field as required.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disable the trigger and picker. The trigger stays focusable and exposes `aria-disabled`; opening is blocked.",
      "default": "false"
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the input is disabled. With isDisabled, shows a tooltip on hover/keyboard focus and describes the trigger (activation stays blocked). Use this instead of wrapping a disabled DateRangeInput in Tooltip."
    },
    {
      "name": "value",
      "type": "DateRange | null",
      "description": "Selected date range or null. Import the `DateRange` type from `@astryxdesign/core/DateRangeInput`; it is `{start: ISODateString, end: ISODateString}`. Do NOT redeclare your own DateRange type; use the exported one so TypeScript structurally matches.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(value: DateRange | null) => void",
      "description": "Callback when the range changes. Called with null on clear.",
      "required": true
    },
    {
      "name": "changeAction",
      "type": "(value: DateRange | null) => void | Promise<void>",
      "description": "Async action fired after onChange. Drives optimistic UI updates via useTransition."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Whether the input is in a loading state. Disables interaction and shows a spinner.",
      "default": "false"
    },
    {
      "name": "min",
      "type": "ISODateString",
      "description": "Minimum selectable date. `ISODateString` is a template literal type (`\\`${number}${number}${number}${number}-${number}${number}-${number}${number}\\``). Pass a string literal like `\"2026-01-28\"`, not a runtime string variable. Import it from `@astryxdesign/core/Calendar` or use `as ISODateString` if computing the value dynamically."
    },
    {
      "name": "max",
      "type": "ISODateString",
      "description": "Maximum selectable date. Same template literal type as `min`: use a YYYY-MM-DD string literal or cast with `as ISODateString`."
    },
    {
      "name": "dateConstraints",
      "type": "Array<(date: Date) => boolean>",
      "description": "Custom constraint functions to disable specific dates."
    },
    {
      "name": "maxRangeSpan",
      "type": "number",
      "description": "Maximum days a selected range may span, counting both endpoints (`7` = a 7-day window, start + 6). Once a start is picked, days beyond this distance are disabled so the range cannot stretch past the cap. Rolling window relative to the start; for fixed calendar bounds use `min`/`max`. Constrains selection only; it never rewrites a `value` already wider than the cap (flag that with `status`)."
    },
    {
      "name": "minRangeSpan",
      "type": "number",
      "description": "Minimum days a selected range must span, counting both endpoints (`2` forbids a single-day range). Once a start is picked, days closer than this are disabled. Clicking the start again commits a one-day range when allowed, or cancels the in-progress selection when the minimum is longer. Defaults to 1 (same-day start and end allowed)."
    },
    {
      "name": "presets",
      "type": "Array<DateRangePreset>",
      "description": "Preset ranges shown as quick-select options beside the calendar, or above it when the two do not fit side by side. A preset is disabled when either endpoint violates min, max, or dateConstraints, or when its span violates minRangeSpan or maxRangeSpan."
    },
    {
      "name": "hasClear",
      "type": "boolean",
      "description": "Shows a clear button when a range is selected.",
      "default": "true"
    },
    {
      "name": "placeholder",
      "type": "string",
      "description": "Placeholder text when no range is selected.",
      "default": "'Select date range'"
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Size of the trigger.",
      "default": "'md'"
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Status indicator for error, warning, or success states."
    },
    {
      "name": "statusVariant",
      "type": "'attached' | 'detached' | 'tooltip'",
      "description": "How the status message is placed relative to the input. attached overlaps directly below the input (bordered treatment); detached floats below as a separate element with spacing; tooltip hides the message box and surfaces it in a tooltip on the status icon.",
      "default": "'attached'"
    },
    {
      "name": "labelTooltip",
      "type": "string",
      "description": "Tooltip text via info icon at label end."
    },
    {
      "name": "numberOfMonths",
      "type": "1 | 2",
      "description": "Number of months in the calendar.",
      "default": "2"
    },
    {
      "name": "weekStartsOn",
      "type": "0 | 1 | 2 | 3 | 4 | 5 | 6 | 'sun' | 'mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat'",
      "description": "First day of week in the calendar. A number (0 = Sunday to 6 = Saturday) or a three-letter day name.",
      "default": "0"
    },
    {
      "name": "calendar",
      "type": "'gregory' | 'iso8601' | 'buddhist' | 'roc' | 'japanese' | 'persian' | 'indian' | 'hebrew' | 'chinese' | 'dangi' | 'coptic' | 'ethiopic' | 'ethioaa' | 'islamic-civil' | 'islamic-tbla' | 'islamic-umalqura'",
      "description": "The calendar the trigger text and the popover calendar show, such as persian, hebrew, or buddhist. value, onChange, min, max, and presets stay Gregorian ISO dates. The field has no typed entry. Calendars other than gregory, iso8601, buddhist, roc, and japanese need Temporal, native or a polyfill the application loads; without it the field shows Gregorian dates and warns in development. Month starts in the Chinese and Dangi calendars come from the runtime's Temporal; when you render on the server, load the same Temporal implementation on the server and in the browser.",
      "default": "the InternationalizationProvider's calendar, else 'gregory'"
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the Field box around the label, control, and status. containerClassName and containerStyle take a class name and inline styles for the same box. No effect (development warning) where no Field box renders: inside InputGroup (style the group) and in a horizontal-labels FormLayout."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the bordered element that holds the text, icons, and end controls, never the native input. controlClassName and controlStyle take a class name and inline styles for the same box. Replaces root xstyle, className, and style, which this component does not accept."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
